/* Sticky bits */
val |= (env->mseccfg & mask);
if ((val ^ env->mseccfg) & mask) {
    tlb_flush(env_cpu(env));
}

if (!MSECCFG_RLB_ISSET(env)) {
    for (i = 0; i < pmp_regions; i++) {
        if (pmp_is_locked(env, i)) {
            val &= ~MSECCFG_RLB;
            break;
        }
    }
}

